def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    starts = list(range(0, w - 1, 3))
    rows = list(range(1, h, 2))
    for i, r in enumerate(rows):
        src = rows[len(rows) - 1 - i]
        for c in starts:
            out[r][c:c+2] = grid[src][c:c+2]
    return out
